import React, { Component } from 'react';
import {
	CButton,
	CCard,
	CCardBody,
	CCardGroup,
	CCol,
	CContainer,
	CForm,
	CInput,
	CInputGroup,
	CInputGroupPrepend,
	CInputGroupText,
	CRow
} from '@coreui/react';
import CIcon from '@coreui/icons-react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { Loading } from '../Statuses/Statuses';
import { Logger, reloadPage } from '../../Utils/Utils';
import { requestHeaderPOSTWithAuth } from '../../Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { BACKEND_TYPING_SPEED_SERVICE_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const initialState = {
	isLoaded: false,
	loadingModalVisible: false,
	loadingModalState: 0,
	failureModalVisible: false,
};

const FILE_NAME = "TypingSourceWebsiteSave.js";

class TypingSourceWebsiteSave extends Component {

	constructor(props) {
		super(props);
		this.state = JSON.parse(JSON.stringify(initialState));
	}

	resetStateToDefault() {
		this.setState(JSON.parse(JSON.stringify(initialState)));
	}

	componentDidMount() {
		document.title = "Satanlabs - Save Source Website";
		this.setState({
			isLoaded: true
		});
	}

	reloadData() {
		this.resetStateToDefault();
		setTimeout(() => {
			this.setState({
				isLoaded: true
			});
		}, 50);
	}

	submitForm = (event) => {
		event.preventDefault();

		let reqData = {
			name: event.target.inputName.value,
			url: event.target.inputUrl.value
		};

		this.setState({
			loadingModalVisible: true,
			loadingModalState: 0
		});

		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/source/save';
		const userData = getUserDataFromLocalStorage();
		fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(reqData), userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_1", "result", result);
				if(result.code === 1001) {
					//success
					this.setState({
						loadingModalState: 1,
					});
					setTimeout(() => {this.reloadData();}, 200);
				} else {
					//something horrible happened
					this.setState({
						loadingModalVisible: false,
						loadingModalState: 0,
						failureModalVisible: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_1", "error", error);
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	render() {
		Logger(FILE_NAME, "render", "", "this.state", this.state);

		return (
			this.state.isLoaded ?
			<div>
				<a href="#/typing-speed/source" style={{ textDecoration: 'none' }}>
					<CButton color="secondary" className="mb-3">← Back to Source Websites</CButton>
				</a>
				<CContainer>
					<CRow className="justify-content-center">
					<CCol md="8">
						<CCardGroup>
						<CCard className="p-4">
							<CCardBody>
							<CForm onSubmit={this.submitForm}>
								<h1>Save Source Website</h1>
								<CInputGroup className="mb-3">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilPencil" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder="Website Name (e.g. MonkeyType)"
									autoComplete="on"
									type="text"
									id="inputName"
									label="Website Name"
									required
								/>
								</CInputGroup>
								<CInputGroup className="mb-4">
								<CInputGroupPrepend>
									<CInputGroupText>
									<CIcon name="cilLink" />
									</CInputGroupText>
								</CInputGroupPrepend>
								<CInput
									placeholder="Website URL (e.g. https://monkeytype.com)"
									autoComplete="on"
									type="url"
									id="inputUrl"
									label="Website URL"
									required
								/>
								</CInputGroup>
								<CRow>
									<CCol xs="6">
										<CButton color="success" className="px-4" type='submit'>SAVE</CButton>
									</CCol>
									<CCol xs="6" className="text-right">
										<CButton color="danger" className="px-0" onClick={() => this.reloadData()}>&nbsp;Reset values&nbsp;</CButton>
									</CCol>
								</CRow>
							</CForm>
							</CCardBody>
						</CCard>
						</CCardGroup>
					</CCol>
					</CRow>
				</CContainer>

				<StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
				<FailureModal visible={this.state.failureModalVisible} />
			</div> : <Loading />
		);
	}
}

export default TypingSourceWebsiteSave;
